-- Beta test catalogue: more Explore styles and ~840 brand products (scripts/brand-explore-seed.cjs).
-- Unpublish before a public release: update public.explore_outfits set published=false where photo_url is not null;
alter table public.explore_outfits drop constraint explore_outfits_style_check,
  add constraint explore_outfits_style_check check(style in ('Streetwear','Minimal','Y2K','Casual','Vintage','Eastern','Formal','Athleisure'));
update public.explore_outfits set rank=rank+100000 where photo_url is not null;
on conflict(id) do update set name=excluded.name,style=excluded.style,category=excluded.category,tags=excluded.tags,photo_url=excluded.photo_url,price_label=excluded.price_label,source_url=excluded.source_url,rank=excluded.rank,published=true;
